'use strict';
(()=>{
 const tr=s=>window.FranklinI18n?.translate(s)||s;
 const API='https://franklin-navigator-membership.onrender.com',root=document.querySelector('[data-member-profile-root]');if(!root)return;
 const node=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;};
 const link=(text,href)=>{const n=node('a',text,'button');n.href=href;return n;};
 const state={profile:null,profiles:[],draft:null,publication:null,busy:false,dirty:false};
 const status=node('p','Loading your member profile…','r37-status');status.setAttribute('role','status');status.setAttribute('aria-live','polite');root.append(status);
 function message(s){status.textContent=s;}
 const messages={AUTH_REQUIRED:'Sign in to manage your profile.',ACTIVE_MEMBERSHIP_REQUIRED:'An active membership is required to save member content. Factual corrections remain free.',PROFILE_VERIFICATION_REQUIRED:'Request access to manage this profile before editing member content.',VERSION_CONFLICT:'This profile changed in another session. Your unsaved text is still here. Reload the saved version before trying again.',PUBLICATION_OWNER_CONFLICT:'Another authorized account manages the published member content. Contact support.',FIELD_NOT_EDITABLE:'Only the listed member-content fields can be changed.',PUBLIC_URL_INVALID:'Use a public HTTPS website address without a password or sign-in token.',SUMMARY_TOO_SHORT:'Write a summary of at least 20 characters.',FIELD_INVALID:'Check the field lengths and remove HTML or unsupported characters.',REVIEWER_NOT_CONFIGURED:'Review is not available yet. Your saved request has not been approved.',PUBLICATION_PERMISSION_REQUIRED:'Confirm that you are authorized to publish this public-facing content.',RATE_LIMITED:'Too many requests. Please try again later.'};
 async function request(path,body){let response;try{response=await fetch(API+path,{method:body?'POST':'GET',credentials:'include',headers:body?{'Content-Type':'application/json'}:undefined,body:body?JSON.stringify(body):undefined});}catch{throw Error('SERVICE_UNAVAILABLE');}let out;try{out=await response.json();}catch{throw Error('SERVICE_UNAVAILABLE');}if(!response.ok){const e=new Error(messages[out.error?.code]||'We could not complete this request. Your unsaved text is still here. Check saved status before retrying.');e.code=out.error?.code;throw e;}return out;}
 async function work(fn){if(state.busy)return;state.busy=true;root.setAttribute('aria-busy','true');try{await fn();}catch(e){message(e.message==='SERVICE_UNAVAILABLE'?'The service is unavailable. Your unsaved text is still here. Check saved status before retrying.':e.message);}finally{state.busy=false;root.removeAttribute('aria-busy');}}
 function button(label,fn,primary=false){const b=node('button',label,primary?'button primary':'button');b.type='button';b.addEventListener('click',()=>work(fn));return b;}
 function field(label,name,type='text',max=1200){const wrap=node('label'),title=node('span',label),input=node(type==='textarea'?'textarea':'input');if(type!=='textarea')input.type=type;input.name=name;input.maxLength=max;input.id='member-'+name;wrap.htmlFor=input.id;wrap.append(title,input);return {wrap,input};}
 const controls=node('div',undefined,'r37-member-step tool'),view=node('div',undefined,'r37-member-step tool');root.append(controls,view);
 async function refresh(){const result=await request('/api/member/profiles');state.profiles=result.profiles;controls.replaceChildren();const l=node('label','Choose your linked profile'),select=node('select');select.id='member-profile-selection';l.htmlFor=select.id;for(const p of state.profiles){const o=node('option',p.name);o.value=p.profile_id;select.append(o);}controls.append(l,select);if(!state.profiles.length){message('Find your profile on the membership page, then request access to manage it.');controls.append(link('Find my profile','/membership-status/'));view.replaceChildren();return;}
  const asked=new URLSearchParams(location.search).get('profile');state.profile=state.profiles.find(p=>p.profile_id===state.profile?.profile_id)||state.profiles.find(p=>p.profile_id===asked)||state.profiles[0];select.value=state.profile.profile_id;
  select.addEventListener('change',()=>{if(state.dirty&&!confirm(tr('Discard unsaved edits and change profiles?'))){select.value=state.profile.profile_id;return;}state.profile=state.profiles.find(p=>p.profile_id===select.value);state.dirty=false;work(load);});
  if(!result.reviewCoverageConfigured)controls.append(node('p','Review coverage has not been confirmed. Requests may be saved, but approval and publication are not promised.','fine-print'));
  await load();
 }
 async function load(){const p=state.profile;const result=await request('/api/member/profile?profileId='+encodeURIComponent(p.profile_id));state.draft=result.draft;state.publication=result.publication;view.replaceChildren();view.append(node('h2',p.name));
  if(p.authority_state!=='VERIFIED'){representation(p);return;}
  editor(p);message('Your saved profile status is up to date.');
 }
 function representation(p){view.append(node('h3','Request profile access'),node('p','Explain your role and provide a public source showing your connection. Do not send passwords, identity documents, private customer records, or payment details.'));
  if(p.public_reason)view.append(node('p',p.public_reason));
  const f=node('form'),url=field('Public evidence website','evidenceUrl','url'),why=field('Your public-facing role and connection','statement','textarea');url.input.required=true;why.input.required=true;why.input.minLength=30;const submit=node('button','Save review request','button primary');submit.type='submit';f.append(url.wrap,why.wrap,submit);f.addEventListener('submit',e=>{e.preventDefault();work(async()=>{const result=await request('/api/member/representation/request',{profileId:p.profile_id,expectedRevision:p.review_revision||0,evidenceUrl:url.input.value,statement:why.input.value});p.review_revision=result.revision;message('Your request is saved and waiting for review. No payment has been started.');});});view.append(f,button('Refresh review status',refresh),link('Get support','/member-support/'));message(p.review_state==='PENDING'?'Your request is saved and waiting for review. No payment has been started.':'Request access to manage this profile before editing member content.');
 }
 function editor(p){const draft=state.draft,labels={DRAFT:'Saved draft — not submitted',SUBMITTED:'Submitted — awaiting review',CHANGES_REQUESTED:'Changes requested',PUBLISHED:'Published member content',REMOVED:'Member content removed'};
  view.append(node('p',labels[draft?.state]||'No saved member draft yet.'),node('p','These fields are member-provided additions. Your public-source identity, credentials, address, and factual corrections stay separate.'));
  if(draft?.public_reason)view.append(node('p',draft.public_reason));
  const form=node('form'),inputs={};for(const [name,label,type,max] of [['summary','About / member description','textarea',1600],['tagline','Short profile tagline','text',180],['services','Services / specialties','textarea',2400],['hours','Hours','textarea',600],['serviceArea','Service area / locations','textarea',600],['accessibility','Accessibility information','textarea',800],['languages','Languages','text',300],['pricing','Pricing / payment information (optional)','textarea',800],['experience','Experience / business history','textarea',1600],['credentials','Credentials / certifications','textarea',1600],['awards','Awards / honors','textarea',1200],['associations','Associations / memberships','textarea',1200],['education','Education / training','textarea',1200],['publications','Publications / media / speaking','textarea',1600],['offersEvents','Offers / events / community participation','textarea',1600],['website','Official website','url',1200],['contactUrl','Contact page','url',1200],['bookingUrl','Booking / appointment page','url',1200],['quoteUrl','Quote / estimate page','url',1200],['menuUrl','Menu page','url',1200],['orderUrl','Order / reservation page','url',1200],['directionsUrl','Directions / location page','url',1200],['profileImageUrl','Public HTTPS logo / profile image URL','url',1200],['galleryUrls','Gallery image URLs — one public HTTPS URL per line','textarea',4000],['socialLinks','Official social / online links — one public HTTPS URL per line','textarea',4000]]){const f=field(label,name,type,max);f.input.value=draft?.fields?.[name]||'';f.input.addEventListener('input',()=>{state.dirty=true;});inputs[name]=f.input;form.append(f.wrap);}
  inputs.summary.required=true;inputs.summary.minLength=20;const save=node('button','Save draft','button primary');save.type='submit';const saveActions=node('div',undefined,'r37-member-actions');saveActions.append(save);form.append(saveActions);
  form.addEventListener('submit',e=>{e.preventDefault();work(async()=>{const values=Object.fromEntries(Object.entries(inputs).map(([k,v])=>[k,v.value]));const saved=await request('/api/member/profile/save',{profileId:p.profile_id,expectedRevision:state.draft?.revision||0,fields:values});state.draft={...saved,fields:values};state.dirty=false;message('Your draft is saved on the server. It is not public.');});});
  const guidance=node('p','Use only public-facing information you are authorized to publish. For gallery and social links, enter one public HTTPS URL per line. Do not enter client, patient, customer, payment, password or confidential information.','fine-print');view.append(form,guidance);const actions=node('div',undefined,'r37-member-actions');view.append(actions);actions.append(button('Submit saved draft for review',async()=>{if(state.dirty){message('Save your edits before submitting for review.');return;}if(!confirm(tr('Confirm that you are authorized to publish this public-facing content.')))return;const result=await request('/api/member/profile/submit',{profileId:p.profile_id,expectedRevision:state.draft?.revision||0,rightsConfirmed:true});state.draft={...state.draft,...result};message('Your saved draft is submitted. It will not replace public content until authorized review approves it.');}),button('Reload saved version',async()=>{if(state.dirty&&!confirm(tr('Discard unsaved edits and reload the saved version?')))return;state.dirty=false;await load();}),link('Free factual correction','/profile-request/'),link('Billing and cancellation','/membership-status/'),link('Get support','/member-support/'));
  if(state.publication){const pub=state.publication;view.append(node('h3','Published member content'),node('p',pub.fields.summary),link('View the public profile','/profiles/'+encodeURIComponent(p.profile_id)+'/'),button('Confirm published profile value',async()=>{const current=await request('/api/member/public-profile?profileId='+encodeURIComponent(p.profile_id));if(!current.publication||current.publication.fields_sha256!==pub.fields_sha256||current.publication.revision!==pub.revision){message('The published version changed. Reload the saved version.');return;}await request('/api/member/profile/readback',{profileId:p.profile_id,revision:pub.revision,fieldsSha256:pub.fields_sha256});message('The published member content has been confirmed. Your first profile-value step is recorded.');}));}
 }
 window.addEventListener('beforeunload',e=>{if(state.dirty){e.preventDefault();e.returnValue='';}});
 work(async()=>{try{await request('/api/accounts/me');await refresh();}catch(e){if(e.code==='AUTH_REQUIRED'){message('Sign in to manage your profile.');controls.append(link('Sign in or create an account','/membership-status/'));}else throw e;}});
})();
